# -*- coding: utf-8 -*-
"""결정 135(과정 교정: 수리자 직접 판단·지시 원문 전달·횡단 단위·다시 보기)를 결정록·운전 장부·작업 장부에 적는다. 2026-11-17."""
import io, datetime
ROOT = r"C:\math\임시\주차함수_증명"
DEC = ROOT + r"\대조v2\장부_설계_세션결정.md"
RUN = ROOT + r"\대조v2\구조압축\운전_장부.md"
LG = ROOT + r"\작업_장부.md"
hm = datetime.datetime.now().strftime("%m-%d %H:%M")[:-1] + "x"

d135 = r"""
135. **구조 압축 캠페인 3단계의 과정 교정 — 수리자의 직접 판단으로 되돌리고 사용자 지시를 원문으로 전달한다(2026-11-17 """ + hm[6:] + r""").** 물결 2가 도는 동안 사용자가 「작업 맥락 복구가 제대로 안 된 것 같은데. 이전에 하던 수리 루프랑 많이 달라」고 짚었고, 세션의 첫 답(5차 이후의 「판정 없는 수리」와 견줌)에 「무엇을 전달하느냐만큼 어떻게 전달하느냐가 중요하니 내가 이전 프롬프트에서 제시한 내용 모두를 원문으로 읽어 왜곡이나 손실 없이 전달해야 해. 그리고 내가 말한 수리 루프는 더 이전에 있어」라고 했다. 세션은 11-11부터 11-17까지 사용자의 메시지 전부를 대화 로그 원문에서 뽑아 읽었다(로컬 보관 `대조v2/구조압축/_사용자메시지_1111_1115.txt`·`_1115이후_정제.txt`; 정본은 대화 로그). 확인한 것: (ㄱ) 「이전에 하던 수리 루프」의 정본은 11-14의 지시들이다 — 다수 독립 검토자를 전체 영역에 주제 한정 없이, 이전 수리 내역을 보여 주지 않고 새로 탐색하게 보낸다 → 보고가 다 오면 판정해 수리를 보낸다 → 「각 수리를 적당히 묶어 별도 작업자에 할당하고 그 작업자가 그 작업 뿐 아니라 그와 둘러싼 이 프로젝트 일반 맥락과 의미를 구체적으로 이해하면서 각 사안 개별적인 판단을 내리면서 유기적으로 그와 연결되어 있는 영역들을 다 자체적으로 끝까지 파고 들어가면서 깔끔하게 진행하게 해 … 스크립트 따위가 아니라 실제로 내용을 읽고 실제로 내용을 직접 수정하게 해」 → 생성기 반영 → 「다시 또 한 번 새롭게, 방금처럼 이전 이력 없이 독립 검토」; 11-15 5차 뒤에는 판정도 수리자의 몫(「'둔다'도 같이 보내서 각자 직접 판단하게」). (ㄴ) 사용자 지시의 전달은 11-14 22:45·22:50의 요구대로 원문 인용으로 한다 — 「내가 반복해서 이전 대화들에서 지시한 매우 구체적이고 세밀한 작업 원리 및 방식 정보 등은 계속 반영되어야 해」, 「내가 실제로 과거 대화에 지시한 그 정확한 지시와 표현들을 모두 세밀하게 살펴보고서는 함축 없이 제대로 이해해서 적어줘」; 그 꼴이 `파견/전체_독립검토8_파견문_1115.md`의 「판단의 방식」 절이다. (ㄷ) 이번 캠페인의 11-17 지시는 「심사 결과를 받아 각 영역마다 다시 직접 세밀하게 살펴보며 … 합당한 판단과 결정을 내려 처리하는 수리자」를 세우고 결정 작업자는 「그 과정에서 구조적이고 통합적인 결정과 선택이 필요하다면」의 보조로 두었는데, 압축 뒤 세션은 결정 단계를 모든 사안으로 넓히고 수리 안내에 수리자를 그 결정의 집행자로 적었다(「결정은 설계서가 내렸다, 네 일은 실행」). 영역별 파견에 더해 요구된 「여러 영역을 묶어서 파견」도 수리에는 없었고, 사용자 선호를 전달하던 읽기 사슬(정합3 1·2·4·5·6절, 수리 공통 1·2절, 전체검토5 1절, 맥락_재구축 11절, 합의 10항, 결정록)도 줄였다. 교정: (1) 수리 공통 안내를 둘째 판으로 다시 썼다(`파견/구조압축_수리_공통_1117.md`) — 2절에 11-17 지시의 문단 여덟과 11-14·11-15의 루프 지시를 「 」 원문 인용으로 싣고 그 아래 수리자에게 요구하는 바를 줄이지 않고 적었다; 심사 보고·결정 문서·설계서는 「판정과 재료」이며 사안마다 수리자가 판단한다(다르게 가면 무엇을 읽고 왜 그렇게 보았는지를 적는다; 「사용자 판단」으로 되돌리지 않는다); 파일 경계를 넘는 라벨·글자·문턱·진술의 꼴만 병행 작업자 사이의 「계약」으로 두고 바꾸면 인계 첫머리에 먼저 적는다; 읽기 사슬을 복원했다. (2) 물결 3에 U10–U13(6장 뒤 절반·7B·9장·10장)과 함께 물결 1·2에서 첫째 판 아래 고쳐진 일곱 장을 둘째 판의 방식으로 다시 보는 R2·R3·R4·R5A·R5B·R7A·R8을 병행으로 둔다(집행된 결정을 포함해 사안마다 다시 판단). (3) 그 뒤 횡단 단위 셋 — H1 7장 환원 경로 전체(6·7A·7B·부록 D 6/7A/7B), H3 둘째 층 두 마무리와 공유 기반(8·9·10장)을 병행하고 H2 2장 일반 진술과 전 장의 특수화(2장과 3–10장의 인용 자리)를 혼자. (4) 물결 4(U14–U18)와 그 뒤의 상한 없는 루프(이력 비공개 독립 검토 → 사안별 직접 판단의 수리 → 생성 → 반복)는 11-14의 루프 정의대로. 물결 1·2의 변경 자체는 되돌리지 않는다 — 심사·결정 문서에 원문 근거가 있고 수리자들도 어긋난 자리에서 스스로 판단했다(보고에 근거 있음); R 단위가 다시 본다. 물결 2는 커밋 3906f779, 지도 갱신 2(라운드12)는 진행 중.
"""
s = io.open(DEC, encoding="utf-8").read(); assert "135. **" not in s
io.open(DEC, "w", encoding="utf-8", newline="\n").write(s.rstrip("\n") + "\n" + d135.lstrip("\n"))

R = io.open(RUN, encoding="utf-8").read()
old = "**물결 2 끝(09:0x; 4장·5A·5B·6A·8장). 사용자 확인 대기 — 과정 교정(수리자 직접 판단·횡단 묶음·읽기 사슬·번역측 전달) 뒤 커밋·지도 갱신 2·물결 3.**"
new = "**물결 2 끝(09:0x)·커밋 3906f779. 과정 교정(결정 135): 수리 공통 안내 둘째 판 — 사용자 지시 원문 인용·수리자 직접 판단·계약·읽기 사슬 복원. 지도 갱신 2 진행 중 → 물결 3(U10–U13 + R2·R3·R4·R5A·R5B·R7A·R8) → H1∥H3 → H2 → 지도 3 → 물결 4 → 지도 4 → 관문·파이프라인·PDF → 루프.**"
assert old in R
R = R.replace(old, new)
R = R.rstrip("\n") + "\n- **사용자 지적과 교정(10:xx)** — 「작업 맥락 복구가 제대로 안 된 것 같은데. 이전에 하던 수리 루프랑 많이 달라」, 「무엇은 전달하느냐 만큼이나 중요한 것은 어떻게 전달하느냐이니만큼 내가 구체적으로 이전 프롬프트에서 제시한 내용 모두를 확실히 원문으로 읽어 네가 이해하고 제대로 왜곡이나 손실 없이 전달해야 해. 그리고 내가 말한 수리 루프는 더 이전에 있어」. 세션이 11-11~11-17 사용자 메시지 전부를 로그 원문에서 뽑아 읽음(로컬 `_사용자메시지_*.txt`). 결정 135. 수리 공통 안내 둘째 판 작성(첫째 판은 git 5a6a4c97·3906f779에 보존). 물결 3 배정표: U10·U11·U12·U13 + R2·R3·R4·R5A·R5B·R7A·R8 → H1·H3 → H2.\n"
io.open(RUN, "w", encoding="utf-8", newline="\n").write(R)

G = io.open(LG, encoding="utf-8").read()
A = " 구조 압축 2단계 회수·설계서·물결 1 파견(이 세션):"
i = G.find(A); assert i > 0 and G.count(A) == 1
j = G.find("\n", i)
line = ("\n- " + hm + " 구조 압축 물결 1·2 회수와 과정 교정(이 세션): 물결 1 커밋 5a6a4c97(2장·3장·7A·four-families 재인증·11.3 생성기), 지도 갱신 1(라운드11), 물결 2 커밋 3906f779(4장·5A·5B·6A·8장). 사용자가 과정의 이탈(수리자가 결정의 집행자로·지시 원문 손실·횡단 묶음 부재)을 짚음 → 사용자 메시지 전부를 로그 원문에서 다시 읽고 결정 135로 교정: 수리 공통 안내 둘째 판(지시 원문 인용·수리자 직접 판단·계약·읽기 사슬 복원), 물결 3에 R 단위 일곱(다시 보기) 추가, 횡단 단위 H1·H3·H2. 지도 갱신 2 진행 중. 다음: 물결 3 파견 → H → 지도 3 → 물결 4 → 지도 4 → 관문·파이프라인·PDF → 상한 없는 루프(이력 비공개 독립 검토 → 사안별 직접 판단 수리 → 생성 → 반복) → 잔여 계산.")
G = G[:j] + line + G[j:]
io.open(LG, "w", encoding="utf-8", newline="\n").write(G)
print("결정 135·운전 장부·작업 장부 ok", hm)
